  export function retry<T>(fn: () => Promise<T>, maxAttempts = 3): Promise<T> {
-   return fn().catch(() => fn().catch(() => fn()));
+   return fn().catch(async (err) => {
+     if (maxAttempts <= 1) throw err;
+     await new Promise(r => setTimeout(r, 1000));
+     return retry(fn, maxAttempts - 1);
+   });
  }

